COPY (WITH ex AS (SELECT rp.captured_at, (r->'fixture'->>'id') fixture_id, (r->'league'->>'id') league_id, (r->'teams'->'home'->>'id') home_id, (r->'teams'->'away'->>'id') away_id FROM raw_payload rp, json_array_elements(rp.payload->'response') r WHERE rp.endpoint='fixtures'), ranked AS (SELECT *, row_number() OVER (PARTITION BY fixture_id ORDER BY captured_at DESC, home_id) rn FROM ex WHERE fixture_id IS NOT NULL AND home_id IS NOT NULL AND away_id IS NOT NULL) SELECT fixture_id, home_id, away_id, league_id FROM ranked WHERE rn=1) TO STDOUT WITH CSV HEADER;
